function Invoke-RegistryBackup {
    <#

    .SYNOPSIS
        Creating a backup registry. 
    #>

    Art -artN "
============================================================
== Backup might take some time - approximation 30 seconds ==
============================================================
" -ch DarkGreen

    Add-Type -AssemblyName System.Windows.Forms
    $FileBrowser = New-Object System.Windows.Forms.SaveFileDialog
    $FileBrowser.Title = "Save Registry Backup"
    $FileBrowser.Filter = "Registry files (*.reg)|*.reg"
    $FileBrowser.DefaultExt = "reg"
    $FileBrowser.AddExtension = $true
    $FileBrowser.InitialDirectory = [Environment]::GetFolderPath("Desktop")

    $DialogResult = $FileBrowser.ShowDialog()

    if ($DialogResult -eq [System.Windows.Forms.DialogResult]::OK) {
        $FilePath = $FileBrowser.FileName
        $TempFilePath = [System.IO.Path]::GetTempFileName()
        $RegistryRoots = @("HKEY_CURRENT_USER", "HKEY_LOCAL_MACHINE", "HKEY_CURRENT_CONFIG")

        foreach ($Root in $RegistryRoots) {
            reg export $Root $TempFilePath /y
            Get-Content -Path $TempFilePath | Out-File -Append -FilePath $FilePath
        }
        Remove-Item -Path $TempFilePath

        Art -artN "
==========================================
== Backup registry created successfully ==
== Location: $FilePath ==
==========================================
" -ch DarkGreen

    Invoke-MessageBox -msg "backup"
    } else {
        Art -artN "
======================================
== Operation cancelled by the user. ==
======================================
" -ch DarkRed
    }
}


function Invoke-ShortcutApp {
    <#

    .SYNOPSIS
        Creates a shortcut and prompts for a save location

    .PARAMETER ShortcutToAdd
        The name of the shortcut to add

    #>
    param($ShortcutToAdd)

        $iconPath = $null
        Switch ($ShortcutToAdd) {
        "Win11Deb" {
            $SourceExe = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
            $IRM = 'irm https://dub.sh/win11deb | iex'
            $Powershell = '-NoProfile -ExecutionPolicy Bypass'
            $ArgumentsToSourceExe = "$powershell $IRM"
            $DestinationName = "Win11Deb.lnk"
            
            $downloadUrl = "https://raw.githubusercontent.com/vukilis/Windows11-Optimizer-Debloater/main/icon.ico"
            $destinationPath = "$env:SystempRoot\win11deb.ico"

            # Check if the file already exists
            if (-not (Test-Path -Path "$env:SystempRoot\win11deb.ico")) {
                # File does not exist, download it
                Invoke-WebRequest -Uri $downloadUrl -OutFile $destinationPath
                Write-Host "File downloaded to: $destinationPath" -ForegroundColor Green
            } else {
                Write-Host "File already exists at: $destinationPath" -ForegroundColor Magenta
            }     
            $iconPath = "$env:SystempRoot\win11deb.ico"
        }
    }

    $FileBrowser = New-Object System.Windows.Forms.SaveFileDialog
    $FileBrowser.InitialDirectory = [Environment]::GetFolderPath('Desktop')
    $FileBrowser.Filter = "Shortcut Files (*.lnk)|*.lnk"
    $FileBrowser.FileName = $DestinationName
    $DialogResult = $FileBrowser.ShowDialog()

    if ($DialogResult -eq [System.Windows.Forms.DialogResult]::OK) {
        $WshShell = New-Object -comObject WScript.Shell
        $Shortcut = $WshShell.CreateShortcut($FileBrowser.FileName)
        $Shortcut.TargetPath = $SourceExe
        $Shortcut.Arguments = $ArgumentsToSourceExe
        if ($null -ne $iconPath) {
            $shortcut.IconLocation = $iconPath
        }
        $Shortcut.Save()

        $bytes = [System.IO.File]::ReadAllBytes($($FileBrowser.FileName))
        $bytes[0x15] = $bytes[0x15] -bor 0x20 #set byte 21 (0x15) bit 6 (0x20) ON
        [System.IO.File]::WriteAllBytes("$($FileBrowser.FileName)", $bytes)

        Art -artN "
Shortcut for $ShortcutToAdd has been saved to $($FileBrowser.FileName)
" -ch DarkGreen

    Invoke-MessageBox -msg "shortcut"
    }else {
        Art -artN "
======================================
== Operation cancelled by the user. ==
======================================
" -ch DarkRed
    }
}

function Invoke-VsCodeMenu {
    <#
    .SYNOPSIS
        Adds "Open with Code" to right-click menu (files + folders + background).
        Uses $env:LOCALAPPDATA dynamically.
    #>

    $codePath = Join-Path $env:LOCALAPPDATA "Programs\Microsoft VS Code\Code.exe"

    if (-not (Test-Path $codePath)) {
        Write-Warning "? VS Code not found at: $codePath"
        return
    }

    # Convert to .reg-safe format (double backslashes)
    $codePathReg = $codePath -replace '\\', '\\\\'

    $regContent = @"
Windows Registry Editor Version 5.00

; Add "Open with Code" for folder background
[HKEY_CLASSES_ROOT\Directory\Background\shell\VSCode]
@="Open with Code"
"Icon"="\"$codePathReg\""

[HKEY_CLASSES_ROOT\Directory\Background\shell\VSCode\command]
@="\"$codePathReg\" \"%V\""

; Add "Open with Code" for files
[HKEY_CLASSES_ROOT\*\shell\VSCode]
@="Open with Code"
"Icon"="\"$codePathReg\""

[HKEY_CLASSES_ROOT\*\shell\VSCode\command]
@="\"$codePathReg\" \"%1\""
"@

    $tempFile = [IO.Path]::GetTempFileName() + ".reg"
    Set-Content -Path $tempFile -Value $regContent -Encoding ASCII

    # Import registry file (requires admin for HKCR)
    Start-Process reg.exe -ArgumentList "import `"$tempFile`"" -Verb RunAs -Wait

    Remove-Item $tempFile -Force
    Write-Host "VS Code context menu added!" -ForegroundColor Green
}

function Invoke-VsCodeMenuRemove {
    <#
    .SYNOPSIS
        Removes "Open with Code" from right-click context menu
        (files + folders + folder background).
    .NOTES
        Requires admin because it touches HKCR.
    #>

    $keys = @(
        "HKCR\*\shell\VSCode",
        "HKCR\Directory\shell\VSCode",
        "HKCR\Directory\Background\shell\VSCode"
    )

    foreach ($key in $keys) {
        Start-Process reg.exe -ArgumentList "delete `"$key`" /f" -Verb RunAs -Wait
    }

    Write-Host "? VS Code context menu removed!" -ForegroundColor Green
}


