            $script:DynamicAppCheckBoxes[$program.id].IsEnabled = $true
            $script:DynamicAppCheckBoxes[$program.id].Foreground = "#a69f6c"
        }
    }
})

$wpf_PkgMgrChoco.Add_Checked({
